mapper.insert:
INSERT INTO INQR_INFO (
    USER_SN, INQR_TYPE_CD, INQR_TTL, INQR_CN, PRVT_PST_YN, REG_DT, MDFCN_DT, RGTR_SN
) VALUES (
    #{userSn}, #{inqrTypeCd}, #{inqrTtl}, #{inqrCn}, #{prvtPstYn}, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{userSn}
)

mapper.sql:
WHERE I.DEL_YN = 'N'
  AND (I.PSTG_STTS_CD = 'NORMAL' OR #{isOperator} = 'Y')
 AND I.USER_SN = #{viewerSn} 
 AND I.INQR_TYPE_CD = #{inqrType} 
 AND I.ANS_STTS_CD = #{ansStts} 

    AND I.INQR_TTL LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
    AND (I.PRVT_PST_YN = 'N' OR I.USER_SN = #{viewerSn} OR #{isOperator} = 'Y')

mapper.select:
SELECT 
  FROM INQR_INFO I
  JOIN USER_ACNT U ON U.USER_SN = I.USER_SN

 AND I.INQR_SN < #{cursor} 
 ORDER BY I.INQR_SN DESC
 LIMIT #{limit}

mapper.update:
UPDATE INQR_INFO
   SET INQR_TYPE_CD = #{inqrTypeCd},
       INQR_TTL = #{inqrTtl},
       INQR_CN = #{inqrCn},
       PRVT_PST_YN = #{prvtPstYn},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{userSn}
 WHERE INQR_SN = #{inqrSn}
   AND USER_SN = #{userSn}
   AND DEL_YN = 'N'

UPDATE INQR_INFO
   SET DEL_YN = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{userSn}
 WHERE INQR_SN = #{inqrSn}
   AND USER_SN = #{userSn}
   AND DEL_YN = 'N'

UPDATE INQR_INFO
   SET ANS_STTS_CD = #{ansSttsCd},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE INQR_SN = #{inqrSn}
   AND DEL_YN = 'N'

mapper.insert:
INSERT INTO INQR_ANS_INFO (
