) VALUES (
    #{inqrSn}, #{ansUserSn}, #{ansCn}, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{ansUserSn}
)

mapper.select:
SELECT ANS_SN, INQR_SN, ANS_USER_SN, DEL_YN
  FROM INQR_ANS_INFO
 WHERE ANS_SN = #{ansSn}

mapper.update:
UPDATE INQR_ANS_INFO
   SET ANS_CN = #{ansCn},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE ANS_SN = #{ansSn}
   AND DEL_YN = 'N'

UPDATE INQR_ANS_INFO
